package com.example.application_service.entity;import jakarta.persistence.*;import java.time.*;import java.util.UUID;
@Entity @Table(name="outbox_events") public class OutboxEvent{@Id private UUID id;@Column(name="aggregate_type")private String aggregateType;@Column(name="aggregate_id")private UUID aggregateId;@Column(name="event_type")private String eventType;@Column(name="event_version")private int eventVersion;@Column(columnDefinition="text")private String payload;@Enumerated(EnumType.STRING)private OutboxStatus status;@Column(name="attempt_count")private int attemptCount;@Column(name="created_at")private Instant createdAt;@Column(name="published_at")private Instant publishedAt;@Column(name="next_attempt_at")private Instant nextAttemptAt;@Column(name="locked_at")private Instant lockedAt;@Column(name="last_error")private String lastError;protected OutboxEvent(){}public OutboxEvent(UUID id,UUID aggregateId,String type,int version,String payload){this.id=id;aggregateType="APPLICATION";this.aggregateId=aggregateId;eventType=type;eventVersion=version;this.payload=payload;status=OutboxStatus.PENDING;createdAt=Instant.now();nextAttemptAt=createdAt;}public void claim(){status=OutboxStatus.IN_PROGRESS;lockedAt=Instant.now();}public void published(){status=OutboxStatus.PUBLISHED;publishedAt=Instant.now();lockedAt=null;lastError=null;}public void failed(String error,int maxAttempts){attemptCount++;status=OutboxStatus.FAILED;lockedAt=null;lastError=error==null?null:error.substring(0,Math.min(1000,error.length()));long seconds=Math.min(300,1L<<Math.min(8,attemptCount));nextAttemptAt=Instant.now().plusSeconds(seconds);if(attemptCount>=maxAttempts)nextAttemptAt=Instant.now().plus(Duration.ofDays(3650));}public UUID getId(){return id;}public UUID getAggregateId(){return aggregateId;}public String getEventType(){return eventType;}public int getEventVersion(){return eventVersion;}public String getPayload(){return payload;}public OutboxStatus getStatus(){return status;}public int getAttemptCount(){return attemptCount;}public Instant getCreatedAt(){return createdAt;}public Instant getPublishedAt(){return publishedAt;}public Instant getNextAttemptAt(){return nextAttemptAt;}}
